static inline bool sym_word_character_set_1(int32_t c) {
  return (c < '('
    ? (c < '\r'
      ? (c < '\t'
        ? c == 0
        : c <= '\n')
      : (c <= '\r' || (c < '#'
        ? c == ' '
        : c <= '%')))
    : (c <= ')' || (c < '['
      ? (c < '='
        ? c == ','
        : c <= '=')
      : (c <= ']' || (c < '}'
        ? c == '{'
        : c <= '}')))));
}

static inline bool sym_path_character_set_1(int32_t c) {
  return (c < ':'
    ? (c < '*'
      ? (c < '"'
        ? c == 0
        : c <= '"')
      : (c <= '*' || c == ','))
    : (c <= '<' || (c < ']'
      ? (c < '['
        ? c == '>'
        : c <= '[')
      : (c <= ']' || (c >= '{' && c <= '|')))));
}

static inline bool sym_path_character_set_2(int32_t c) {
  return (c < ':'
    ? (c < '*'
      ? (c < '"'
        ? c == 0
        : c <= '"')
      : (c <= '*' || c == ','))
    : (c <= '<' || (c < ']'
      ? (c < '['
        ? c == '>'
        : c <= '[')
      : (c <= ']' || (c >= '{' && c <= '}')))));
}

